{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE TABLe IF NOT EXISTS hyuman-wh.maplemonk.Final_sku_master ( MARKETPLACE_SKU string, commonsku string, color_sku string, parent_sku string, PRODUCT_name string, category string, product_sub_category string, image_url string, MRP int64 ); CREATE OR REPLACE TEMPORARY TABLE temp_extracted_data AS SELECT saleorderdto, JSON_EXTRACT_ARRAY(saleorderdto, \'$.saleOrderItems\') AS saleOrderItems, JSON_EXTRACT_ARRAY(saleorderdto, \'$.shippingPackages\') AS shippingPackages, JSON_EXTRACT_ARRAY(saleorderdto, \'$.returns\') AS returns, JSON_EXTRACT_SCALAR(saleorderdto, \'$.billingAddress.pincode\') AS PINCODE, JSON_EXTRACT_SCALAR(saleorderdto, \'$.channel\') AS marketplace, JSON_EXTRACT_SCALAR(saleorderdto, \'$.source\') AS source, JSON_EXTRACT_SCALAR(saleorderdto, \'$.code\') AS order_id, JSON_EXTRACT_SCALAR(saleorderdto, \'$.displayOrderCode\') AS reference_code, JSON_EXTRACT_SCALAR(saleorderdto, \'$.billingAddress.phone\') AS phone, JSON_EXTRACT_SCALAR(saleorderdto, \'$.billingAddress.name\') AS name, JSON_EXTRACT_SCALAR(saleorderdto, \'$.billingAddress.email\') AS email, datetime(timestamp_millis(CAST(JSON_EXTRACT_SCALAR(saleorderdto, \'$.updated\') AS int)), \"Asia/Kolkata\") AS SHIPPING_LAST_UPDATE_DATE, JSON_EXTRACT_SCALAR(saleorderdto, \'$.currencyCode\') AS currency, JSON_EXTRACT_SCALAR(saleorderdto, \'$.billingAddress.city\') AS city, JSON_EXTRACT_SCALAR(saleorderdto, \'$.billingAddress.state\') AS state, JSON_EXTRACT_SCALAR(saleorderdto, \'$.status\') AS ORDER_STATUS, datetime(timestamp_millis(CAST(JSON_EXTRACT_SCALAR(saleorderdto, \'$.displayOrderDateTime\') AS int)), \"Asia/Kolkata\") AS order_Date, CASE WHEN REPLACE(JSON_EXTRACT_SCALAR(saleorderdto, \'$.cod\'), \'\"\', \'\') = \'true\' THEN \'COD\' ELSE \'Prepaid\' END AS payment_mode, CASE WHEN REPLACE(JSON_EXTRACT_SCALAR(saleorderdto, \'$.code\'), \'\"\', \'\') = \'true\' THEN \'COD\' ELSE \'Prepaid\' END AS payment_method FROM hyuman-wh.maplemonk.Unicommerce_hyuman_GET_ORDERS_BY_IDS ; CREATE OR REPLACE TEMPORARY TABLE temp_order_related AS SELECT ed.PINCODE as pincode, ed.marketplace as marketplace, ed.source as source, ed.order_id as ordeR_id, ed.reference_code reference_code, ed.phone phone, ed.name name, ed.email email, ed.SHIPPING_LAST_UPDATE_DATE SHIPPING_LAST_UPDATE_DATE, JSON_EXTRACT_SCALAR(item, \'$.itemSku\') AS sku, JSON_EXTRACT_SCALAR(item, \'$.sellerSkuCode\') AS Marketplace_sku, JSON_EXTRACT_SCALAR(item, \'$.channelProductId\') AS product_id, JSON_EXTRACT_SCALAR(item, \'$.itemName\') AS product_name, ed.currency currency, ed.city city, ed.state state, JSON_EXTRACT_SCALAR(item, \'$.statusCode\') as order_status, ed.order_Date ordeR_date, CAST(JSON_EXTRACT_SCALAR(item, \'$.shippingCharges\') AS FLOAT64) AS shipping_price, 1 AS SUBORDER_QUANTITY, CAST(JSON_EXTRACT_SCALAR(item, \'$.discount\') AS FLOAT64) AS discount, CAST(JSON_EXTRACT_SCALAR(item, \'$.totalIntegratedGst\') AS FLOAT64) AS tax, CAST(JSON_EXTRACT_SCALAR(item, \'$.sellingPrice\') AS FLOAT64) AS SELLING_PRICE, JSON_EXTRACT_SCALAR(item, \'$.shippingPackageCode\') AS shippingPackageCode, JSON_EXTRACT_SCALAR(item, \'$.shippingPackageStatus\') AS shippingPackageStatus, JSON_EXTRACT_SCALAR(item, \'$.code\') AS saleOrderItemCode, CAST(JSON_EXTRACT_SCALAR(item, \'$.id\') AS STRING) AS SALES_ORDER_ITEM_ID, JSON_EXTRACT_SCALAR(item, \'$.facilityName\') AS warehouse_name, JSON_EXTRACT_SCALAR(shippingPackages,\'$.trackingNumber\') AS AWB, datetime(timestamp_millis(CAST(JSON_EXTRACT_SCALAR(shippingPackages,\'$.invoiceDate\') AS int)), \"Asia/Kolkata\") AS invoiceDate, JSON_EXTRACT_SCALAR(shippingPackages,\'$.invoiceCode\') invoiceCode, ed.payment_mode, ed.payment_method FROM temp_extracted_data ed LEFT JOIN UNNEST(ed.saleOrderItems) AS item LEFT JOIN UNNEST(ed.shippingPackages) AS shippingPackages; CREATE OR REPLACE TEMPORARY TABLE temp_shipping_related AS WITH extracted_items AS ( SELECT REPLACE(JSON_EXTRACT_SCALAR(A, \'$.shippingProvider\'), \'\"\', \'\') AS courier, REPLACE(JSON_EXTRACT_SCALAR(A, \'$.status\'), \'\"\', \'\') AS shipping_status, datetime(timestamp_millis(CAST(JSON_EXTRACT_SCALAR(A, \'$.dispatched\') AS int)), \"Asia/Kolkata\") AS dispatched, datetime(timestamp_millis(CAST(JSON_EXTRACT_SCALAR(A, \'$.delivered\') AS int)), \"Asia/Kolkata\") AS delivered, JSON_EXTRACT_SCALAR(A, \'$.code\') AS shippingPackageCode, c.order_id, JSON_EXTRACT(A, \'$.items\') AS items FROM temp_extracted_data c LEFT JOIN UNNEST(c.shippingPackages) A ) SELECT c.*, cast(JSON_EXTRACT_SCALAR(value, \'$.quantity\') AS int64) AS shippedQuantity, JSON_EXTRACT_SCALAR(value, \'$.itemSku\') AS itemSku, FROM extracted_items c left join UNNEST(REGEXP_EXTRACT_ALL(items, r\'\{[^{}]+\}\')) AS value; CREATE OR REPLACE TEMPORARY TABLE temp_returns AS WITH extracted_return_data AS ( SELECT ed.order_id, ed.reference_code, JSON_EXTRACT_ARRAY(A, \'$.returnItems\') AS returnItems FROM temp_extracted_data ed LEFT JOIN UNNEST(ed.returns) AS A ) SELECT erd.order_id AS ordeR_id, erd.reference_code, REPLACE(JSON_EXTRACT_SCALAR(B, \'$.saleOrderItemCode\'), \'\"\', \'\') AS saleOrderItemCode, REPLACE(JSON_EXTRACT_SCALAR(B, \'$.itemSku\'), \'\"\', \'\') AS itemSku FROM extracted_return_data erd LEFT JOIN UNNEST(erd.returnItems) AS B WHERE REPLACE(JSON_EXTRACT_SCALAR(B, \'$.saleOrderItemCode\'), \'\"\', \'\') IS NOT NULL; create or replace table hyuman-wh.maplemonk.hyuman_UNICOMMERCE_fact_items_intermediate_final as SELECT o.pincode, o.marketplace, o.source, o.order_id, o.reference_code, o.phone, o.name, o.email, o.SHIPPING_LAST_UPDATE_DATE, o.sku, o.Marketplace_sku, o.product_id, o.product_name, o.currency, o.city, o.state, o.ORDER_STATUS, invoiceCode, invoiceDate, o.order_date , o.shipping_price, o.SUBORDER_QUANTITY, o.discount, o.tax, ifnull(o.SELLING_PRICE,0) + ifnull(O.shipping_price,0) as SELLING_PRICE, o.shippingPackageCode, o.shippingPackageStatus, o.saleOrderItemCode, o.SALES_ORDER_ITEM_ID, o.AWB, o.warehouse_name, o.payment_mode, o.payment_method, s.courier, s.shipping_status, s.shippedQuantity, s.dispatched AS Dispatch_date, s.delivered AS Delivered_Date, CASE WHEN r.itemSku IS NOT NULL THEN 1 ELSE 0 END AS return_flag, CASE WHEN (CASE WHEN r.itemSku IS NOT NULL THEN 1 ELSE 0 END) = 1 THEN o.SUBORDER_QUANTITY ELSE 0 END AS return_quantity, CASE WHEN order_status = \'CANCELLED\' THEN o.SUBORDER_QUANTITY ELSE 0 END AS cancelled_quantity, null AS new_customer_flag, null AS acquisition_product, CASE WHEN UPPER(order_status) = \'COMPLETE\' THEN CAST(s.delivered AS DATE) - CAST(order_date AS DATE) ELSE CAST(CURRENT_DATE AS DATE) - CAST(order_date AS DATE) END AS days_in_shipment, FROM temp_order_related o LEFT JOIN temp_shipping_related s ON o.shippingPackageCode = s.shippingPackageCode AND o.sku = s.itemSku AND o.order_id = s.order_id LEFT JOIN temp_returns r ON r.saleOrderItemCode = o.saleOrderItemCode AND r.order_id = o.order_id ; create or replace table maplemonk.hyuman_unicommerce_fact_items_temp as select pincode, marketplace, source, order_id, reference_code, phone, name, email, SHIPPING_LAST_UPDATE_DATE, sku, Marketplace_sku, product_id, product_name, currency, city, state, ORDER_STATUS, invoiceCode, invoiceDate, order_date, shipping_price, SUBORDER_QUANTITY, discount, tax, SELLING_PRICE, shippingPackageCode, shippingPackageStatus, saleOrderItemCode, SALES_ORDER_ITEM_ID, AWB, warehouse_name, payment_mode, payment_method, courier, shipping_status, shippedQuantity, Dispatch_date, Delivered_Date, return_flag, return_quantity, cancelled_quantity, new_customer_flag, acquisition_product, days_in_shipment from `hyuman-wh.maplemonk.hyuman_UNICOMMERCE_fact_items_intermediate_final` Union all select Billing_Address_Pincode as pincode, Channel_Name as marketplace, Channel_Name as source, replace(Sale_Order_Code,\'`\',\'\') as order_id, replace(Sale_Order_Code,\'`\',\'\') as reference_code, Billing_Address_Phone as phone, Billing_Address_Name as name, cast(null as string) as email, CASE WHEN Updated LIKE \'%-%\' THEN PARSE_DATETIME(\'%Y-%m-%d %H:%M:%S\', Updated) WHEN Updated LIKE \'%/%\' THEN PARSE_DATETIME(\'%d/%m/%Y %H:%M:%S\', Updated) ELSE NULL END AS SHIPPING_LAST_UPDATE_DATE, Item_SKU_Code as sku, Seller_SKU_Code as Marketplace_sku, Channel_Product_Id as product_id, SKU_Name as product_name, currency, Shipping_Address_city as city, Shipping_Address_state state, Sale_Order_item_status as ORDER_STATUS, invoice_Code as invoicecode, CASE WHEN invoice_Created LIKE \'%-%\' THEN PARSE_DATETIME(\'%Y-%m-%d %H:%M:%S\', invoice_Created) WHEN invoice_Created LIKE \'%/%\' THEN PARSE_DATETIME(\'%d/%m/%Y %H:%M:%S\', invoice_Created) ELSE NULL END as invoiceDate, CASE WHEN Order_Date_as_dd_mm_yyyy_hh_MM_ss LIKE \'%-%\' THEN PARSE_DATETIME(\'%Y-%m-%d %H:%M:%S\', Order_Date_as_dd_mm_yyyy_hh_MM_ss) WHEN Order_Date_as_dd_mm_yyyy_hh_MM_ss LIKE \'%/%\' THEN PARSE_DATETIME(\'%d/%m/%Y %H:%M:%S\', Order_Date_as_dd_mm_yyyy_hh_MM_ss) ELSE NULL END AS order_date, cast(shipping_charges as float64) as shipping_price, 1 as SUBORDER_QUANTITY, safe_cast(discount as float64) discount, safe_cast(tax_value as float64) tax, safe_cast(total_price as float64) selling_price, Shipping_Package_Code as shippingPackageCode, Shipping_Package_Status_Code as shippingPackageStatus, Sale_Order_Item_Code as saleOrderItemCode, Sale_Order_Item_Code as SALES_ORDER_ITEM_ID, Tracking_Number as AWB, facility as warehouse_name, Payment_Instrument as payment_mode, case when cast(COD as int64) = 1 then \'COD\' else \'Prepaid\' end payment_method, Shipping_Courier as courier, Shipping_Courier_Status as shipping_status, case when lower(Sale_Order_Item_status) not like \'%cancel%\'then 1 else 0 end shippedQuantity, CAST((CASE WHEN Dispatch_date LIKE \'%-%\' THEN PARSE_DATETIME(\'%Y-%m-%d %H:%M:%S\', Dispatch_date) WHEN Dispatch_date LIKE \'%/%\' THEN PARSE_DATETIME(\'%d/%m/%Y %H:%M:%S\', Dispatch_date) ELSE NULL END) as datetime) AS Dispatch_date, CAST((CASE WHEN Delivery_time LIKE \'%-%\' THEN PARSE_DATETIME(\'%Y-%m-%d %H:%M:%S\', Delivery_time) WHEN Delivery_time LIKE \'%/%\' THEN PARSE_DATETIME(\'%d/%m/%Y %H:%M:%S\', Delivery_time) ELSE NULL END) AS datetime) AS Delivered_date, case when return_date is not null then 1 else 0 end return_flag, case when return_date is not null then 1 else 0 end return_quantity, case when lower(Sale_Order_Item_status) like \'%cancel%\'then 1 else 0 end cancelled_quantity, null new_customer_flag, null acquisition_product, CASE WHEN UPPER(Sale_Order_Item_status) LIKE \'%DELIVERED%\' THEN CASE WHEN Delivery_time LIKE \'%-%\' THEN PARSE_DATETIME(\'%Y-%m-%d %H:%M:%S\', Delivery_time) WHEN Delivery_time LIKE \'%/%\' THEN PARSE_DATETIME(\'%d/%m/%Y %H:%M:%S\', Delivery_time) ELSE NULL END - (CASE WHEN Order_Date_as_dd_mm_yyyy_hh_MM_ss LIKE \'%-%\' THEN PARSE_DATETIME(\'%Y-%m-%d %H:%M:%S\', Order_Date_as_dd_mm_yyyy_hh_MM_ss) WHEN Order_Date_as_dd_mm_yyyy_hh_MM_ss LIKE \'%/%\' THEN PARSE_DATETIME(\'%d/%m/%Y %H:%M:%S\', Order_Date_as_dd_mm_yyyy_hh_MM_ss) ELSE NULL END) ELSE CAST(CURRENT_DATE AS DATE) - (CASE WHEN Order_Date_as_dd_mm_yyyy_hh_MM_ss LIKE \'%-%\' THEN PARSE_DATETIME(\'%Y-%m-%d %H:%M:%S\', Order_Date_as_dd_mm_yyyy_hh_MM_ss) WHEN Order_Date_as_dd_mm_yyyy_hh_MM_ss LIKE \'%/%\' THEN PARSE_DATETIME(\'%d/%m/%Y %H:%M:%S\', Order_Date_as_dd_mm_yyyy_hh_MM_ss) ELSE NULL END) END AS days_in_shipment from hyuman-wh.maplemonk.unicommerce_historical_sale_orders where replace(Sale_Order_Code,\'`\',\'\') not in (select distinct order_id from `hyuman-wh.maplemonk.hyuman_UNICOMMERCE_fact_items_intermediate_final`) ; create or replace table hyuman-wh.maplemonk.hyuman_customerID_test_Final as with new_phone_numbers as ( select contact_num ,9700000000 + row_number() over( order by contact_num asc ) as maple_monk_id from ( select distinct SUBSTR(REGEXP_REPLACE(REPLACE(phone, \' \', \'\'),\'[^a-zA-Z0-9]\',\'\'),-10) as contact_num from hyuman-wh.maplemonk.hyuman_unicommerce_fact_items_temp ) a ), int as ( select contact_num,email,coalesce(maple_monk_id,id2) as maple_monk_id from ( select contact_num, email,maple_monk_id,9800000000+row_number() over(partition by maple_monk_id is NULL order by email asc ) as id2 from ( select distinct coalesce(p.contact_num,SUBSTR(REGEXP_REPLACE(REPLACE(e.contact_num, \' \', \'\'),\'[^a-zA-Z0-9]\',\'\'),-10)) as contact_num, e.email,maple_monk_id from ( select replace(phone,\' \',\'\') as contact_num,email from hyuman-wh.maplemonk.hyuman_unicommerce_fact_items_temp ) e left join new_phone_numbers p on p.contact_num = SUBSTR(REGEXP_REPLACE(REPLACE(e.contact_num, \' \', \'\'),\'[^a-zA-Z0-9]\',\'\'),-10) ) a ) b ) select contact_num,email,case when email is not null and email <> \'\' then min(maple_monk_id) over (partition by email ) else maple_monk_id end maple_monk_id from int where coalesce(contact_num,email) is not NULL; create or replace table hyuman-wh.maplemonk.hyuman_unicommerce_fact_items as select coalesce(c.maple_monk_id,c.maple_monk_id) customer_id, o.*, CASE WHEN marketplace IN (\'hyuman_MEESHO\') THEN \'Meesho\' WHEN marketplace IN (\'FLIPKART\', \'FK_BNG\') THEN \'Flipkart\' WHEN marketplace IN (\'hyuman_AJIO\') THEN \'Ajio\' WHEN marketplace IN (\'hyuman_MYNTRA\') THEN \'Myntra\' WHEN marketplace LIKE \'AMAZON%\' THEN \'Amazon\' WHEN marketplace LIKE \'SHOPIFY%\' THEN \'Shopify\' WHEN marketplace = \'TATACLIQ1\' THEN \'TataCliq\' ELSE \'Others\' END AS mapped_marketplace, min(order_date) over(partition by coalesce(c.maple_monk_id,c.maple_monk_id)) as acquisition_date from hyuman-wh.maplemonk.hyuman_unicommerce_fact_items_temp o left join (select distinct contact_num phone,maple_monk_id from hyuman-wh.maplemonk.hyuman_customerID_test_Final )c on replace(c.phone,\' \',\'\') = replace(o.phone,\' \',\'\') where o.order_date is not null; CREATE OR REPLACE TABLE hyuman-wh.maplemonk.hyuman_unicommerce_fact_items_TEMP_Category AS SELECT fi.*, p.SKUCODE AS SKU_CODE, UPPER(p.PRODUCT_name) AS PRODUCT_NAME_Final, p.product_sub_category, UPPER(p.commonsku) AS commonsku, p.color_sku, p.parent_sku, p.image_url, p.mrp, sku.Size AS sku_Size, sku.gender AS sku_gender, sku.vertical AS sku_vertical, sku.Product_ID AS sku_Product_ID, sku.Variant_ID AS sku_Variant_ID, sku.style_code AS sku_style_code, sku.Variant_SKU AS sku_Variant_SKU, sku.Product_type AS sku_Product_type, sku.product_title AS sku_product_title, upper(sm.category) AS Product_category, upper(sm.colour) as Product_Colour, sku.Product_status AS sku_Product_status, sku.Product_vendor AS sku_Product_vendor FROM `hyuman-wh.maplemonk.hyuman_unicommerce_fact_items` fi LEFT JOIN ( SELECT * FROM `hyuman-wh.maplemonk.hyuman_SKU_MASTER` QUALIFY ROW_NUMBER() OVER ( PARTITION BY LOWER(Variant_SKU) ORDER BY Variant_ID ) = 1 ) sku ON LOWER(fi.sku) = LOWER(sku.Variant_SKU) LEFT JOIN ( select * from ( select *, row_number() over (partition by marketplace_sku order by 1) as rw from maplemonk.hyuman_WH_FINAL_SKU_MASTER where marketplace_sku <> \'\' ) where rw=1 ) sm ON lower(fi.sku) = lower(sm.marketplace_sku) LEFT JOIN ( SELECT MARKETPLACE_SKU AS SKUCODE, commonsku, color_sku, parent_sku, PRODUCT_name, category, CAST(NULL AS STRING) AS product_sub_category, image_url, MRP FROM `hyuman-wh.maplemonk.Final_sku_master` ) p ON LOWER(fi.sku) = LOWER(p.commonsku) ; CREATE OR REPLACE TABLE hyuman-wh.maplemonk.hyuman_unicommerce_fact_items AS SELECT * FROM ( select *, row_number() over (partition by reference_code,saleorderitemcode order by SHIPPING_LAST_UPDATE_DATE desc) rw1 from hyuman-wh.maplemonk.hyuman_unicommerce_fact_items_TEMP_Category ) where rw1 = 1; CREATE OR REPLACE TEMPORARY TABLE temp_extracted_data_return AS SELECT saleorderdto, JSON_EXTRACT_ARRAY(saleorderdto, \'$.returns\') AS returns, JSON_EXTRACT_ARRAY(saleorderdto, \'$.returns.returnItems\') AS returnItems, JSON_EXTRACT_SCALAR(saleorderdto, \'$.channel\') AS Marketplace, JSON_EXTRACT_SCALAR(saleorderdto, \'$.source\') AS Source, JSON_EXTRACT_SCALAR(saleorderdto, \'$.code\') AS order_id, JSON_EXTRACT_SCALAR(saleorderdto, \'$.displayOrderCode\') AS reference_code, JSON_EXTRACT_SCALAR(saleorderdto, \'$.billingAddress.phone\') AS phone, JSON_EXTRACT_SCALAR(saleorderdto, \'$.billingAddress.email\') AS email, datetime(timestamp_millis(CAST(JSON_EXTRACT_SCALAR(saleorderdto, \'$.displayOrderDateTime\') AS int)), \"Asia/Kolkata\") AS order_date FROM hyuman-wh.maplemonk.Unicommerce_hyuman_GET_ORDERS_BY_IDS_final ; CREATE OR REPLACE TEMPORARY TABLE temp_return_data AS SELECT ed.marketplace, ed.source, ed.order_id, ed.phone, ed.email, ed.order_date, ed.reference_code, REPLACE(JSON_EXTRACT_SCALAR(A, \'$.code\'), \'\"\', \'\') AS return_display_code, REPLACE(JSON_EXTRACT_SCALAR(A, \'$.statusCode\'), \'\"\', \'\') AS return_status, REPLACE(JSON_EXTRACT_SCALAR(B, \'$.itemName\'), \'\"\', \'\') AS return_Item, REPLACE(JSON_EXTRACT_SCALAR(B, \'$.itemSku\'), \'\"\', \'\') AS return_sku, REPLACE(JSON_EXTRACT_SCALAR(B, \'$.saleOrderItemCode\'), \'\"\', \'\') AS return_saleOrderItemCode, REPLACE(JSON_EXTRACT_SCALAR(B, \'$.inventoryType\'), \'\"\', \'\') AS return_inventory_type, datetime(timestamp_millis(CAST(JSON_EXTRACT_SCALAR(A, \'$.inventoryReceivedDate\') AS int)), \"Asia/Kolkata\") AS inventory_received_date, datetime(timestamp_millis(CAST(JSON_EXTRACT_SCALAR(A, \'$.returnCompletedDate\') AS int)), \"Asia/Kolkata\") AS return_complete_date, REPLACE(JSON_EXTRACT_SCALAR(A, \'$.returnInvoiceDisplayCode\'), \'\"\', \'\') AS return_invoice_display_code, REPLACE(JSON_EXTRACT_SCALAR(A, \'$.shippingProvider\'), \'\"\', \'\') AS return_courier, REPLACE(JSON_EXTRACT_SCALAR(A, \'$.providerStatus\'), \'\"\', \'\') AS return_provider_shipping_status, REPLACE(JSON_EXTRACT_SCALAR(A, \'$.trackingNumber\'), \'\"\', \'\') AS return_tracking_number, REPLACE(JSON_EXTRACT_SCALAR(A, \'$.type\'), \'\"\', \'\') AS return_type FROM temp_extracted_data_return ed LEFT JOIN UNNEST(ed.returns) AS A LEFT JOIN UNNEST(JSON_EXTRACT_ARRAY(A,\'$.returnItems\')) AS B qualify row_number() over (partition by reference_code,REPLACE(JSON_EXTRACT_SCALAR(B, \'$.saleOrderItemCode\'), \'\"\', \'\') order by order_date asc)=1; CREATE OR REPLACE TABLE hyuman-wh.maplemonk.hyuman_UNICOMMERCE_RETURNS_INTERMEDIATE AS SELECT rd.marketplace, rd.source, rd.order_id, rd.phone, rd.email, rd.order_date, rd.reference_code, case when rd.return_display_code is not null then 1 else 0 end as return_flag, rd.return_display_code, rd.return_status, rd.inventory_received_date, rd.return_complete_date, rd.return_invoice_display_code, rd.return_courier, rd.return_provider_shipping_status, rd.return_tracking_number, rd.return_type, rd.return_saleOrderItemCode, rd.return_sku, rd.return_Item, rd.return_inventory_type, CASE WHEN marketplace IN (\'hyuman_MEESHO\') THEN \'Meesho\' WHEN marketplace IN (\'FLIPKART\', \'FK_BNG\') THEN \'Flipkart\' WHEN marketplace IN (\'hyuman_AJIO\') THEN \'Ajio\' WHEN marketplace IN (\'hyuman_MYNTRA\') THEN \'Myntra\' WHEN marketplace LIKE \'AMAZON%\' THEN \'Amazon\' WHEN marketplace LIKE \'SHOPIFY%\' THEN \'Shopify\' WHEN marketplace = \'TATACLIQ1\' THEN \'TataCliq\' ELSE \'Others\' END AS mapped_marketplace, FROM temp_return_data rd ; create or replace table hyuman-wh.maplemonk.hyuman_UNICOMMERCE_RETURNS as select ri.*, p.SKUCODE AS SKU_CODE, upper(p.PRODUCT_name) as PRODUCT_NAME_Final, Upper(p.CATEGORY) AS Product_Category, p.product_sub_category, Upper(p.commonsku) AS commonsku, p.color_sku, p.parent_sku, p.image_url, p.mrp from hyuman-wh.maplemonk.hyuman_UNICOMMERCE_RETURNS_INTERMEDIATE ri left join (select MARKETPLACE_SKU skucode, commonsku, color_sku, parent_sku, PRODUCT_name, category, cast(null as string) AS product_sub_category, image_url, MRP from hyuman-wh.maplemonk.Final_sku_master ) p on lower(ri.return_sku) = lower(p.commonsku) ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            